window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["13"]={"https://www.gov.uk/foreign-travel-advice/cameroon":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"6103b2e8242f206ca17e4a112256b538e150c356c42483da5d4b23dca0d196dc","read":"https://www.gov.uk/api/content/foreign-travel-advice/cameroon","bytes":66786,"x":"fulltext v1","title":"Cameroon travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-27T00:00:00+00:00","mod":"2026-11-06T16:22:46+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"hs","s":["Bakassi Peninsula"]},{"k":"p","s":["FCDO advises against all travel to Bakassi Peninsula."]},{"k":"hs","s":["Cameroon-Central African Republic border"]},{"k":"p","s":["FCDO advises against all travel to within 40km of the border with Central African Republic."]},{"k":"hs","s":["Cameroon-Chad border"]},{"k":"p","s":["FCDO advises against all travel to within 40km of the border with Chad."]},{"k":"hs","s":["Cameroon-Nigeria border"]},{"k":"p","s":["FCDO advises against all travel to within 40km of the border with Nigeria, except for Garoua in the North Region."]},{"k":"hs","s":["Far-North Region"]},{"k":"p","s":["FCDO advises against all travel to the Far-North Region, except for:"]},{"k":"li","s":["a 20km radius to the north, east and west of Maroua"]},{"k":"li","s":["30km south of Maroua"]},{"k":"hs","s":["North-West Region"]},{"k":"p","s":["FCDO advises against all travel to the North-West Region."]},{"k":"hs","s":["South-West Region"]},{"k":"p","s":["FCDO advises against all travel to the South-West Region, including the towns of Buea, Muyuka and Tiko in Fako Division. Except for:"]},{"k":"li","s":["Limbé"]},{"k":"li","s":["the 35km stretch of the N3 road connecting Limbé to the Littoral Region in Fako Division"]},{"k":"hs","s":["Limbé"]},{"k":"p","s":["FCDO advises against all but essential travel to Limbé and the 35km stretch of the N3 road connecting Limbé to the Littoral Region in Fako Division, South-West Region."]},{"k":"hs","s":["North Region, Adamawa Region and Maroua"]},{"k":"p","s":["FCDO advises against all but essential travel to the North Region, including Garoua,, and a 20km radius to the north, east and west of Maroua, and 30km south of Maroua, in Far-North Region."]},{"k":"hs","s":["Adamawa Region"]},{"k":"p","s":["FCDO advises against all but essential travel to within 20km of the border with the North region of Cameroon. FCDO advises against all travel to within 40km of the Central African Republic (CAR) and Nigeria borders."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/cameroon/regional-risks"],"."]},{"k":"h","s":["Support from the UK government"]},{"k":"p","s":["The British High Commission can only offer limited support for British nationals in areas where we advise against travel."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/cameroon/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Cameroon’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Cameroon set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Cameroon High Commission in the UK","https://cameroonhighcommission.co.uk/"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Cameroon, your passport must have an ‘expiry date’ at least 6 months after the date you arrive."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to enter Cameroon."]},{"k":"p","s":["You must apply for a e-visa online – some people encounter technical problems with this online service, so apply in good time."]},{"k":"p","s":["You cannot get a visa on arrival at either Yaoundé or Douala airport."]},{"k":"p","s":["If you travel to Cameroon by road or sea, you must get a physical visa before you arrive by applying at your nearest Cameroon embassy or high commission. You cannot get an e-visa at land or sea borders."]},{"k":"p","s":["If you are in Cameroon and have questions about your immigration status, contact the General Delegation for National Security in Yaoundé:"]},{"k":"p","s":["Telephone: +237 22221 2884"]},{"k":"p","s":["Make sure you get your passport stamped."]},{"k":"p","s":["Make sure the border control officer puts a stamp in your passport."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To enter Cameroon, you must have a certificate to prove you’ve had a yellow fever vaccination."]},{"k":"p","s":["For more details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Cameroon guide","https://travelhealthpro.org.uk/country/40/cameroon#Vaccine_Recommendations"],"."]},{"k":"h","s":["Health screening"]},{"k":"p","s":["In response to the current Ebola outbreak in DRC, you may be required to undergo thermal screening on arrival at Nsimalen International Airport and Douala International Airport. These measures are subject to change at short notice."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of Cameroon. You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"h","s":["Safety and security"]},{"k":"p","s":["This guide also has safety advice for ",["regions of Cameroon","https://www.gov.uk/foreign-travel-advice/cameroon/regional-risks"],"."]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Cameroon"]},{"k":"p","s":["Terrorists are very likely to try to carry out attacks in Cameroon."]},{"k":"p","s":["Terrorist attacks could be indiscriminate, including in places visited by foreigners such as:"]},{"k":"li","s":["restaurants"]},{"k":"li","s":["bars"]},{"k":"li","s":["markets"]},{"k":"li","s":["hotels"]},{"k":"li","s":["shopping centres"]},{"k":"li","s":["places of worship"]},{"k":"li","s":["parks"]},{"k":"li","s":["sporting venues"]},{"k":"p","s":["The terrorist groups Boko Haram and Islamic State West Africa (ISWA) are mainly active in the Far-North Region but attacks could occur anywhere, including major towns and cities such as Yaoundé and Douala. There was an increase in the use of improvised explosive devices by violent extremist organisations in the Far-North Region in 2023. Stay aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["There are occasional isolated incidents of political unrest around the country. You should stay alert, avoid large gatherings and monitor local media."]},{"k":"p","s":["Political developments and increased tensions related to the English-speaking North-West and South-West regions could lead to isolated incidents of violence in other parts of the country. This could affect western interests, as well as places frequented by foreigners. Plan your movements carefully. In November 2020, a threat by non-state armed groups was made against diplomatic missions in Yaoundé, including the British High Commission."]},{"k":"hs","s":["Bomb attacks"]},{"k":"p","s":["Non-state armed groups are increasingly using improvised explosive devices (IEDs) to target civilians in the North-West and South-West regions and against government forces in the Far-North Region. IEDs have also been seen in the capital Yaoundé."]},{"k":"p","s":["There could be more attacks in urban areas, or other locations around the country. Stay alert and keep up to date with developments through the media and local authorities."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Armed robbery"]},{"k":"p","s":["There is risk of armed robbery and mugging throughout Cameroon, particularly in the cities Yaoundé, Douala, Ngaoundere and Bafoussam."]},{"k":"p","s":["Avoid isolated or less developed areas of towns for example, Briqueterie and Mokolo market in Yaoundé and Nkololun, New Bell, Akwa, Bonaberi and Village in Douala. Be cautious at all times when walking, particularly alone, and avoid walking at night."]},{"k":"hs","s":["Burglary and petty theft"]},{"k":"p","s":["Close and lock all doors and windows, particularly at night. Make sure burglar proof metal bars are installed. Identify callers through spy holes before opening doors, especially late at night."]},{"k":"p","s":["Petty theft is common on trains, coaches and bush taxis and around bus stations and hotels. Be particularly careful with your belongings."]},{"k":"hs","s":["Unofficial taxis"]},{"k":"p","s":["Taxis in cities operate like buses, picking up passengers while there is still room in the car. They often take indirect routes, and many do not meet basic safety requirements. There have been violent assaults and robberies on taxi passengers. Do not hail taxis from the roadside (these are yellow in Yaoundé and Douala). Only use trusted, pre-arranged taxis, and preferably book one from your hotel or restaurant."]},{"k":"hs","s":["Violent crime near borders and roads"]},{"k":"p","s":["There are incidents of carjacking, criminal kidnapping and armed robbery along roads close to the borders with Central African Republic, Chad and Nigeria:"]},{"k":"li","s":["Bamenda-Banyo road"]},{"k":"li","s":["Bafoussam-Banyo road"]},{"k":"li","s":["Bafoussam-Doula road"]},{"k":"li","s":["Yaoundé-Garoua road"]},{"k":"li","s":["Boulai-Ngaoundere road"]},{"k":"p","s":["Keep car doors locked and windows closed. Avoid wearing jewellery, keep mobile phones out of sight and only carry small amounts of cash and valuables."]},{"k":"hs","s":["Criminal kidnapping"]},{"k":"p","s":["There have been incidents of kidnapping and hostage taking for ransom by large gangs in the Far-North, North, Adamawa, East, North-West and South-West regions of Cameroon."]},{"k":"p","s":["The long-standing policy of the British government is not to make substantive concessions to hostage takers. The British government considers that paying ransoms and releasing prisoners increases the risk of further hostage taking."]},{"k":"hs","s":["Adoption scams"]},{"k":"p","s":["Scam artists often target foreign visitors and residents. The scams come in many forms and can cause significant financial loss. Scammers also use websites, chatrooms and email to target people and companies in the UK."]},{"k":"p","s":["Advance fee scams are common in Cameroon. Criminals use child adoption to persuade victims to pay large amounts of money before they suspect anything. Be very cautious about sending money or travelling to Cameroon to adopt a child where the information has come from a website or through emails. Cameroon does not have adoption agencies."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Always carry ID, either a residence permit or a certified copy of your passport showing a valid visa. The police can detain you if you do not have ID."]},{"k":"hs","s":["Camouflage clothing"]},{"k":"p","s":["It is illegal to wear camouflage clothing unless you are in the armed forces. Penalties may include a fine and detention."]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Penalties for using and possessing drugs are severe and usually include a prison sentence."]},{"k":"hs","s":["Using cameras in secure areas"]},{"k":"p","s":["It is illegal to photograph military sites, government buildings, airports and ports. While photography elsewhere is not illegal, communities can be sensitive to people taking photos or may ask for money in return. Officials may also ask you for money, perhaps suggesting that you need to pay for a ‘permit’ to photograph certain places."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex relationships are not widely accepted in central African society, and same-sex sexual acts are illegal in Cameroon. Same-sex partners have been arrested and prosecuted."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Wildlife, animal products and souvenirs"]},{"k":"p","s":["It is illegal to buy, sell, kill or capture any protected wild animal or trade its parts without a licence. If you are caught buying or trafficking these goods, you’ll be prosecuted and could get a prison sentence or a fine."]},{"k":"hs","s":["Money"]},{"k":"p","s":["It is difficult to exchange sterling travellers cheques in Cameroon. Many banks will only allow you to exchange travellers cheques if you hold an account with them. Euros and US dollars are the most widely accepted foreign currency."]},{"k":"p","s":["Shops usually require small notes, which can be difficult to obtain."]},{"k":"p","s":["You must pay heavy fees to make cash withdrawals from UK bank accounts and ATMs. ATMs are not often available outside of large towns."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Cameroon, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in Cameroon for up to 6 months. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"]," or get the ",["correct version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"],"."]},{"k":"p","s":["If you are staying for more than 6 months, you must get a Cameroonian licence from the Delegation of Transport as soon as possible."]},{"k":"p","s":["Make sure any car you hire is adequately insured, preferably by written confirmation from the insurance company (rather than the car hire firm). If you’re hiring a driver and car, make sure you’re not liable for accidents or damage."]},{"k":"hs","s":["Driving standards"]},{"k":"p","s":["Driving standards are poor in Cameroon."]},{"k":"p","s":["Roads are generally in poor condition. Many are heavily potholed and are unlit at night. Pedestrians and stray animals are a hazard. Many vehicles have poor-quality lights."]},{"k":"p","s":["Avoid travelling at night in Cameroon, particularly in rural areas. Accidents are common on the Yaoundé-Douala road."]},{"k":"p","s":["If you’re travelling between cities, consider taking a VHF radio or satellite phone, as mobile phone coverage is limited. Plan your journey carefully, and travel in convoy if possible."]},{"k":"hs","s":["Roadblocks"]},{"k":"p","s":["Police and gendarmerie roadblocks are common in Cameroon. You may need to show your passport, driving licence or vehicle registration documents."]},{"k":"p","s":["Uniformed members of the security forces stop motorists for minor or non-existent violations of vehicle regulations to extort small bribes. Do not pay bribes – instead ask the officer for a ticket setting out the alleged offence, so you can pay at a local court."]},{"k":"hs","s":["Air travel"]},{"k":"p","s":["Camair-Co is the only local airline operating between some of the major cities. Scheduled flights are often delayed or cancellations. Due to aviation safety standards, we advise against taking flights that use the XIAN MA-60, which is used occasionally for internal flights."]},{"k":"p","s":["Check whether your tour operator has concerns about airlines in Cameroon."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Cameroon. It only covers regions where FCDO has specific advice."]},{"k":"p","s":["You should also read FCDO’s ",["overall travel advice","https://www.gov.uk/foreign-travel-advice/cameroon"]," and ",["safety and security advice","https://www.gov.uk/foreign-travel-advice/cameroon/safety-and-security"],"."]},{"k":"h","s":["The Bakassi Peninsula"]},{"k":"p","s":["FCDO advises against all travel to the Bakassi Peninsula."]},{"k":"p","s":["There have been armed robberies and incidents of piracy in the Gulf of Guinea, particularly in the waters around the Niger Delta and the Bakassi Peninsula. The ferry that operates between Limbé and Tiko in Cameroon and Calabar in Nigeria passes through areas where pirates operate. Cameroon’s Rapid Intervention Brigade patrols the waters, but it is difficult to police the Bakassi Peninsula’s mangrove forests and isolated islands. Mariners should get professional security advice and take appropriate precautions."]},{"k":"h","s":["Cameroon-Central African Republic border"]},{"k":"p","s":["FCDO advises against all travel to within 40km of the border with Central African Republic (CAR)."]},{"k":"p","s":["Large, armed criminal gangs and highway bandits have stopped travellers and taken hostages for ransom, particularly in the east of Cameroon, close to the CAR border. Violence frequently spills across the CAR border into Cameroon. Incidents like these are more likely due to the ongoing insecurity in CAR."]},{"k":"h","s":["Cameroon-Chad border"]},{"k":"p","s":["FCDO advises against all travel to within 40km of the border with Chad."]},{"k":"p","s":["There is a risk of armed banditry, including poachers in Bouba Ndjida National Park in the North Region."]},{"k":"h","s":["Cameroon-Nigeria border"]},{"k":"p","s":["FCDO advises against all travel to within 40km of the border with Nigeria, except for Garoua in the North Region."]},{"k":"h","s":["Far-North Region"]},{"k":"p","s":["FCDO advises against all travel to the Far-North Region, except for:"]},{"k":"li","s":["a 20km radius to the north, east and west of Maroua"]},{"k":"li","s":["30km south of Maroua"]},{"k":"p","s":["Terrorist groups are active in the Far-North Region, ",["see terrorism","https://www.gov.uk/foreign-travel-advice/cameroon/safety-and-security"],". There is also a general threat of kidnapping, criminality and armed banditry."]},{"k":"p","s":["Nigerian military operations in the Nigerian states of Borno, Yobe and Adamawa could have an impact across the border in Cameroon. There have also been a number of reported civilian fatalities in these regions at or near checkpoints due to accidental discharge of weapons."]},{"k":"h","s":["North-West and South-West regions"]},{"k":"p","s":["FCDO advises against all travel to the North-West Region."]},{"k":"p","s":["FCDO advises against all travel to the South-West Region, including the towns of Buea, Muyuka and Tiko in Fako Division. Except for:"]},{"k":"li","s":["Limbé"]},{"k":"li","s":["the 35km stretch of the N3 road connecting Limbé to the Littoral region in Fako Division"]},{"k":"p","s":["Non-state armed groups (NSAGs) sometimes use improvised explosive devices (IEDs) to target civilians in the North-West and South-West regions."]},{"k":"p","s":["Civilians have been killed at or near road checkpoints controlled by NSAGs or government forces. Be cautious when you approach roadblocks."]},{"k":"p","s":["In recent years Cameroonian security forces and NSAGs have fought multiple times in many parts of the North-West and South-West regions. Restrictions including night curfews and a ban on public meetings are in place in some areas. There is a high risk of violent crime, especially at night."]},{"k":"p","s":["There have also been a number of reported civilian fatalities in these regions at or near checkpoints due to accidental discharge of weapons."]},{"k":"p","s":["If you decide to travel to, or within, areas of the English-speaking regions where the FCDO advises against all travel or all but essential travel, you should consider carefully the risks of travel. Monitor developments closely, keep a low profile and minimise your movements."]},{"k":"hs","s":["General strikes"]},{"k":"p","s":["General strikes (or ‘ghost towns’) are called in the English-speaking North-West and South-West regions each Monday. There are often additional days, including in February (around Youth Day, 11 February), May (around National Day on 20 May) and around 1 October (Unofficial Unification Day). There is often violence and travel disruption on these days."]},{"k":"p","s":["As events develop, be cautious and regularly check news reports, this travel advice and information from local authorities."]},{"k":"hs","s":["Lake Nyos"]},{"k":"p","s":["Lake Nyos in the North-West Region emitted carbon dioxide in 1986, suffocating about 1,700 people without warning. Although the Cameroon authorities now closely monitor the lake, this situation could repeat with limited warning. The authorities are also concerned that the volcanic dam holding back Lake Nyos is not sufficiently strong. Nearby Lake Mounoun is also saturated with carbon dioxide."]},{"k":"h","s":["Limbé"]},{"k":"p","s":["FCDO advises against all but essential travel to Limbé and the 35km stretch of N3 road connecting Limbé to the Littoral Region in Fako Division, South-West Region."]},{"k":"h","s":["North Region, and Maroua"]},{"k":"p","s":["FCDO advises against all but essential travel to the North Region, including Garoua,, and a 20km radius to the north, east and west of Maroua, and 30km south of Maroua, in Far-North Region."]},{"k":"h","s":["Adamawa Region"]},{"k":"p","s":["FCDO advises against all but essential travel to within 20km of the border with the North region of Cameroon. FCDO advises against all travel to within 40km of the Central African Republic (CAR) and Nigeria borders."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 112 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Cameroon","https://travelhealthpro.org.uk/country/40/cameroon#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Cameroon","https://travelhealthpro.org.uk/country/40/cameroon"],", including:"]},{"k":"li","s":["Zika virus"]},{"k":"li","s":["malaria and dengue"]},{"k":"li","s":["yellow fever"]},{"k":"li","s":["cholera"]},{"k":"p","s":["Altitude sickness is a risk in parts of Cameroon. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Cameroon"]},{"k":"p","s":["Medical facilities in Cameroon are below UK standards. Emergency facilities are extremely limited. For serious medical treatment, medical evacuation to Europe will be necessary. Make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment abroad and repatriation."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Cameroon"]},{"k":"p","s":["Ambulance: 112"]},{"k":"p","s":["Fire: 119"]},{"k":"p","s":["Police: 117"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=cameroon"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=cameroon"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=cameroon"]," in Cameroon"]},{"k":"li","s":["dealing with a ",["death in Cameroon","https://www.gov.uk/guidance/what-to-do-after-a-british-person-dies-in-cameroon"]]},{"k":"li","s":["being ",["arrested or imprisoned in Cameroon","https://www.gov.uk/government/publications/cameroon-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"]," such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/cameroon/british-high-commission-yaounde"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/cameroon/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Cameroon","https://www.gov.uk/government/publications/cameroon-overseas-business-risk"]," on how to manage political, economic, and business security-related risks."]}],"chars":22120,"change":"New information about the introduction of health screening on arrival at Nsimalen International Airport and Douala International Airport ('Entry requirements' page)."},"https://www.gov.uk/foreign-travel-advice/grenada":{"r":"govuk","at":"2026-11-17T16:38Z","sha":"cc0d086878e05ed3f706dcde3100d81ff18accf5a487d8d0b1810a16965fb8c7","read":"https://www.gov.uk/api/content/foreign-travel-advice/grenada","bytes":54671,"x":"fulltext v1","title":"Grenada travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-11T00:00:00+00:00","mod":"2025-12-10T13:53:19+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/grenada/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Grenada’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Grenada set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Grenadian High Commission in the UK","https://grenada-highcommission.co.uk/"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To visit Grenada, your passport must have an ‘expiry date’ at least 6 months after the date you arrive."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"p","s":["Make sure you get your passport stamped."]},{"k":"p","s":["Make sure the border control officer puts a stamp in your passport. If you do not get a stamp in your passport, you’ll be considered an illegal visitor."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can visit Grenada without a visa."]},{"k":"p","s":["On entry, you’ll be allowed to stay for a maximum period of 3 months."]},{"k":"p","s":["To stay longer (to work or study, for business travel or for other reasons), you must meet the Grenada Immigration Department’s entry requirements."]},{"k":"p","s":["It’s illegal to overstay the entry period or to work without a work permit."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To enter Grenada, you must have a certificate to prove you’ve had a yellow fever vaccination if you’re coming from a ",["country listed as a transmission risk","https://nathnacyfzone.org.uk/factsheet/65/countries-with-risk-of-yellow-fever-transmission"],"."]},{"k":"p","s":["For full details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Grenada guide","https://travelhealthpro.org.uk/country/93/grenada#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of Grenada. You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Grenada"]},{"k":"p","s":["Although there’s no recent history of terrorism in Grenada, attacks cannot be ruled out."]},{"k":"h","s":["Crime"]},{"k":"p","s":["Most crime in Grenada is non-violent and opportunistic, such as thefts of unattended items or burglaries from villas or cars. There are occasional violent crimes including armed robbery and sexual assault."]},{"k":"p","s":["To reduce the risk to yourself and your belongings:"]},{"k":"li","s":["make sure your accommodation is secure – this also applies if you’re staying on a yacht"]},{"k":"li","s":["take care when walking alone off main roads"]},{"k":"li","s":["take particular care around large gatherings, including street and beach parties, especially after dark or during the festival season"]},{"k":"li","s":["avoid isolated areas, including beaches, after dark"]},{"k":"li","s":["only use licensed taxis"]},{"k":"li","s":["do not carry large amounts of cash or jewellery"]},{"k":"li","s":["keep valuables and travel documents in your hotel safe or a safety deposit box"]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Laws on clothing"]},{"k":"p","s":["It’s illegal for anyone, including children, to dress in camouflage clothing."]},{"k":"hs","s":["Illegal drugs penalties"]},{"k":"p","s":["There are severe penalties for all drug offences. Pack all luggage yourself and do not carry anything through customs for anyone else."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Local attitudes towards the LGBT+ community are mostly conservative throughout the Caribbean. Certain same-sex sexual acts are illegal in Grenada. Showing affection in public could receive unwanted and negative attention. It is uncommon for opposite or same-sex couples to show affection in public in Grenada."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"hs","s":["Swimming safety"]},{"k":"p","s":["Currents can be deceptively strong and not all beaches have lifeguards or warning flags. Get local advice before swimming."]},{"k":"p","s":["See ",["water safety on holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],". You must have a temporary Grenadian driving licence. Your car hire company will help you get one, and you’ll need to show a UK driving licence."]},{"k":"p","s":["Hire car companies often have stricter requirements for their customers, such as a year of driving experience, a higher minimum age and holding an international driving permit (IDP)."]},{"k":"p","s":["Roads can have potholes and speed bumps. Minor roads and roads in rural areas are often narrow and may have blind corners. Drivers do not always use indicators. Pedestrians often walk on the roads."]},{"k":"p","s":["Some roads are unlit at night. Road signs and hazards may not be easily visible."]},{"k":"p","s":["Do not stop if you’re flagged down by pedestrians. Keep car doors locked when driving. If you have an accident, call the police and do not move the vehicle."]},{"k":"hs","s":["Taxis and minibuses"]},{"k":"p","s":["Taxis are not metered. There are standard taxi fares for most destinations. To avoid being overcharged, agree the fare in local currency with the driver before you set off. You can often pay in US dollars as well as East Caribbean dollars."]},{"k":"p","s":["If you use private taxis, you can ask the driver to observe speed limits, but minibus drivers often exceed them."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Hurricanes"]},{"k":"p","s":["Hurricane Beryl made landfall on the islands of Carriacou and Petite Martinique in July 2024, and there continues to be reduced tourist infrastructure as rebuilding efforts continue. If you plan to travel to either island, check with your travel agent or accommodation provider about any disruption you may face."]},{"k":"p","s":["The hurricane season in the Caribbean normally runs from June to November. Monitor local news and check the warnings on the US National Hurricane Center."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["Earthquakes are a risk in the Caribbean and tremors are occasionally felt in Grenada. The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"hs","s":["Volcanic eruptions"]},{"k":"p","s":["Check the ",["alert level of the underwater volcano ‘Kick ‘em Jenny’","https://uwiseismic.com/volcanoes/kick-em-jenny/kej-monitoring/"],", located 5 miles off the coast of Grenada. Observe any maritime exclusion zones and follow the advice of the local authorities if there is increased activity or an eruption."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 434 for St George’s general hospital, 724 for Princess Alice hospital in Grenville, or 774 for Princess Royal hospital in Carriacou and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company promptly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["the latest ",["vaccine recommendations for Grenada","https://travelhealthpro.org.uk/country/93/grenada#Vaccine_Recommendations"]]},{"k":"li","s":["where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Grenada","https://travelhealthpro.org.uk/country/93/grenada"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Grenada"]},{"k":"p","s":["The main government hospital can cope with many types of treatment but serious cases may need emergency evacuation."]},{"k":"p","s":["Medical treatment in Grenada can be expensive. Make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment and repatriation."]},{"k":"p","s":["FCDO has a ",["medical providers in Grenada","https://www.gov.uk/government/publications/grenada-list-of-medical-facilities-practitioners"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Grenada"]},{"k":"p","s":["Ambulance: 434 for St George’s general hospital, 724 for Princess Alice hospital in Grenville, or 774 for Princess Royal hospital in Carriacou."]},{"k":"p","s":["Fire: 911"]},{"k":"p","s":["Police: 911"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding ",["lawyers in Grenada","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=grenada"]]},{"k":"li","s":["dealing with a ",["death in Grenada","https://www.gov.uk/guidance/when-someone-dies-in-grenada"]]},{"k":"li","s":["being ",["arrested or imprisoned in Grenada","https://www.gov.uk/government/publications/grenada-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/grenada/british-high-commission-st-george"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/grenada/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":10566,"change":"New information about dual nationals returning to the UK (‘Entry requirements’ page)."},"https://www.gov.uk/foreign-travel-advice/luxembourg":{"r":"govuk","at":"2026-11-17T17:03Z","sha":"bcf2d18f614bafb1f78f553995938c479bc0bc0ca089535bcbfcd8f65c1e764c","read":"https://www.gov.uk/api/content/foreign-travel-advice/luxembourg","bytes":58737,"x":"fulltext v1","title":"Luxembourg travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2012-12-19T00:00:00+00:00","mod":"2026-08-11T10:19:44+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/luxembourg/email-signup"]," when this advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/travelaware/"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of the current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Luxembourg set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Luxembourg Embassy in the UK","https://londres.mae.lu/en/service_citoyens.html"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Luxembourg follows ",["Schengen area rules","https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm"],". Your passport must:"]},{"k":"li","s":["have a ‘date of issue’ less than 10 years before the date you arrive – if you renewed your passport before 1 October 2018, it might have a date of issue that is more than 10 years ago, making it invalid for entry to the Schengen area"]},{"k":"li","s":["have an ‘expiry date’ at least 3 months after the day you plan to leave the Schengen area (the expiry date does not need to be within 10 years of the date of issue)"]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can ",["travel without a visa to the Schengen area","https://www.gov.uk/travel-to-eu-schengen-area"],", which includes Luxembourg, for up to 90 days in any 180-day period. This applies if you travel:"]},{"k":"li","s":["as a tourist"]},{"k":"li","s":["to visit family or friends"]},{"k":"li","s":["to attend business meetings, cultural or sports events"]},{"k":"li","s":["for short-term studies or training"]},{"k":"p","s":["The ",["requirements for working in Luxembourg","https://www.gov.uk/guidance/travel-to-luxembourg-for-work"]," are different."]},{"k":"p","s":["If you’re travelling to other Schengen countries as well, make sure your whole visit is within the 90-day limit. Visits to Schengen countries in the 180 days before you travel count towards your 90 days. If you overstay the 90-day visa-free limit, you may be banned from entering Schengen countries for up to 3 years."]},{"k":"p","s":["At Luxembourg border control, you may also need to:"]},{"k":"li","s":["show proof of your accommodation, for example, a hotel booking confirmation or proof of address for a second home"]},{"k":"li","s":["show proof of your travel insurance"]},{"k":"li","s":["show a return or onward ticket"]},{"k":"li","s":["prove that you have enough money for your stay – the amount varies depending on your accommodation"]},{"k":"hs","s":["Staying longer than 90 days in a 180-day period"]},{"k":"p","s":["To stay longer, you must meet the Luxembourg government’s entry requirements. Check which type of visa or permit you need with the ",["Luxembourg Embassy in the UK","https://londres.mae.lu/en/service_citoyens.html"],"."]},{"k":"p","s":["If you’re in Luxembourg with a residence permit or long-stay visa, this does not count towards your 90-day visa-free limit."]},{"k":"p","s":["Read about ",["entry processes if you live in Luxembourg","https://www.gov.uk/guidance/living-in-luxembourg#passports-and-travel"],"."]},{"k":"h","s":["New Schengen entry requirements"]},{"k":"p","s":["The European Union’s (EU) new Entry/Exit System (EES) is now being implemented across the Schengen area."]},{"k":"p","s":["This means that when you travel into the Schengen area for short stays, you may need to register your biometric details, such as fingerprints and a photo. There is no cost for EES registration."]},{"k":"p","s":["On your first visit into a Schengen country, you may be asked to register your details at a special booth before proceeding to the immigration desk. Follow directions from your travel operator or the staff at your port of entry. You may also need to provide either your fingerprint or photo when you leave the Schengen area. Children aged 11 or younger will not have their fingerprints scanned but can be required to have their photo taken."]},{"k":"p","s":["You do not need to take any action before you arrive at the border on entry to the Schengen area, but EES may take each passenger extra time to complete so be prepared to wait longer than usual at the border and to allow more time for immigration controls when you depart the Schengen area. If you are departing the Schengen area by plane, allow extra time to reach your departure gate as EES checks may take place before boarding."]},{"k":"p","s":["EES is replacing the previous system of manually stamping passports when visitors arrive in the Schengen area for short stays. You may be asked to input biometric details every time you enter or exit."]},{"k":"p","s":["If you enter the Schengen area through the Port of Dover, Eurotunnel at Folkestone or Eurostar at St Pancras International, any information will be taken at the border before you leave the UK."]},{"k":"p","s":["Your digital EES record is valid for 3 years."]},{"k":"p","s":["Read more ",["information on the EU Entry/Exit System and to understand which countries are in the Schengen area","https://www.gov.uk/guidance/eu-entryexit-system"],"."]},{"k":"p","s":["If you are long-term resident in a Schengen country, you are exempt from EES in all Schengen countries. The full list of EES exemptions is on ",["the EU’s official Travel Europe website.","https://travel-europe.europa.eu/en/ees/to-whom-does-ees-not-apply"]]},{"k":"p","s":["If you believe you have been incorrectly entered into EES or your record of time spent in the Schengen area is incorrect, approach border officials when you next cross the Schengen border and request a correction. If you are exempt, carry documentation confirming your status. If you believe your time spent in the Schengen area has been recorded incorrectly, raise this with border officials and be prepared to provide supporting evidence if requested."]},{"k":"h","s":["Additional Border Controls in Belgium"]},{"k":"p","s":["Belgium has introduced additional entry checks until December 2025, although these are not currently planned for the Luxembourg-Belgium border. Checks may be carried out on major roads leading into Belgium, motorway car parks, international bus services, international trains and on intra-Schengen flights. Checks may involve verifying travel documents and identification, as well as screening for illegal substances. In Belgium you must carry your passport with you at all times."]},{"k":"h","s":["Border controls at Germany’s land borders"]},{"k":"p","s":["There are temporary border controls in place to travel into Germany. Check the ",["entry requirements for Germany","https://www.gov.uk/foreign-travel-advice/germany/entry-requirements"],"."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Luxembourg guide","https://travelhealthpro.org.uk/country/132/luxembourg#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Luxembourg","https://douanes.public.lu/fr/voyages-demenagement.html"]," (in French). You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking food into Luxembourg"]},{"k":"p","s":["You cannot take ",["meat, milk or products containing them into EU countries","https://ec.europa.eu/food/animals/animalproducts/personal_imports_en"],". There are some exceptions such as powdered baby milk, baby food and special foods or pet feed required for medical reasons."]},{"k":"hs","s":["Taking money into or out of Luxembourg"]},{"k":"p","s":["Before you travel, ",["declare cash or travellers cheques","https://guichet.public.lu/en/citoyens/immigration/nouveau-resident-luxembourg/declaration-devises/declaration-paiement-devises.html"]," if the value is 10,000 euros or more, even if you are just travelling through (transiting) Luxembourg. You will get a certified declaration to show you brought it in with you. If you do not, your money could be seized when you leave."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Luxembourg"]},{"k":"p","s":["Terrorist attacks in Luxembourg cannot be ruled out."]},{"k":"h","s":["Crime"]},{"k":"p","s":["Violent crime is not common in Luxembourg cities. However, violent robberies have happened."]},{"k":"p","s":["Report any thefts in person to the nearest police station within 24 hours and get a police report crime number for insurance purposes."]},{"k":"hs","s":["Protecting your belongings"]},{"k":"p","s":["Pickpockets operate on buses and in train stations, particularly in the main train station, Gare de Luxembourg. Hotel lobbies in the Findel area are reported to be hotspots for thefts and pickpocketing. To reduce your risk:"]},{"k":"li","s":["do not keep your passport, credit cards and other valuables in the same place"]},{"k":"li","s":["keep your belongings close to you in restaurants and bars"]},{"k":"li","s":["avoid being distracted around tourist attractions and ATMs"]},{"k":"hs","s":["Scams"]},{"k":"p","s":["Scammers can target foreign visitors and residents. Be cautious and make sure you have all the information you need before you provide any personal or bank details."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Alcohol laws"]},{"k":"p","s":["The minimum legal drinking age is 16. Being drunk and disorderly in public is a criminal offence that can result in arrest for a night and a heavy fine."]},{"k":"hs","s":["Illegal drugs"]},{"k":"p","s":["Illegal drugs, including cannabis, carry severe penalties. You should expect a long jail sentence and heavy fines for possessing, using or smuggling illegal drugs, including when transiting through the airport."]},{"k":"p","s":["The airport in Luxembourg has excellent technology and security for detecting illegal items. This is also used to scan the baggage of transiting passengers."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Luxembourg, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"]," and check the rules of the road in the RAC’s Luxembourg guide. The guide lists driving regulations and other legal requirements you need to be aware of."]},{"k":"p","s":["The Luxembourg authorities strictly enforce road traffic laws. You can get a fine for minor violations."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in Luxembourg for one year. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"]," or get the ",["correct version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," as well. The minimum age for driving a car is 18."]},{"k":"p","s":["Within one year of taking up residence in Luxembourg, you must convert your UK licence into a Luxembourg licence. See ",["guidance on driving if you live in Luxembourg","https://www.gov.uk/guidance/living-in-luxembourg#driving-in-luxembourg"],"."]},{"k":"p","s":["Hire car companies often have stricter requirements for their customers, such as a year of driving experience, a higher minimum age and holding an IDP."]},{"k":"p","s":["You must carry these documents in the vehicle or face a fine:"]},{"k":"li","s":["driving licence"]},{"k":"li","s":["vehicle registration document"]},{"k":"li","s":["car insurance certificate"]},{"k":"li","s":["road tax"]},{"k":"li","s":["MOT certificate"]},{"k":"p","s":["Carry your passport because it’s easy to cross into neighbouring countries without realising it."]},{"k":"p","s":["Drink-driving is a serious offence in Luxembourg. The blood alcohol limit for experienced drivers is 0.05% (in England it’s 0.08%). If you’ve had your licence less than 2 years, the limit is 0.02%. You could get a fine and possible imprisonment if you’re caught over the limit."]},{"k":"hs","s":["Winter tyres"]},{"k":"p","s":["Your vehicle must have regulation winter tyres if you drive in winter conditions such as black ice, packed snow, slush, ice sheets or frost. You must add winter tyres or all-weather tyres marked with ‘M.S.’, ‘M+S’, ‘M&S’ or the alpine symbol on all wheels of the vehicle."]},{"k":"p","s":["All drivers must follow these regulations, regardless of their vehicle’s country of registration. You will get a fine if you do not have the correct tyres."]},{"k":"p","s":["For more information, see ",["Luxembourg winter tyre regulations","https://guichet.public.lu/en/citoyens/transport/transports-individuels/vehicule-motorise/controle-technique-pneumatiques/pneus-hiver.html"],"."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["It is safer to use official taxis at clearly marked taxi stands. Official taxis display a price list. Check the rate per kilometre before you get into a taxi – some may charge highly inflated prices. Drivers are allowed to charge extra in the evenings and on Sunday."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 112 and ask for an ambulance."]},{"k":"p","s":["If you ask for a SAMU (‘Service d’Aide Medicale Urgente’), a doctor will come with an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Luxembourg","https://travelhealthpro.org.uk/country/132/luxembourg#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Luxembourg","https://travelhealthpro.org.uk/country/132/luxembourg#General_Information"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Luxembourg"]},{"k":"p","s":["FCDO has a ",["list of medical providers in Luxembourg","https://www.gov.uk/government/publications/luxembourg-list-of-medical-facilitiespractitioners"]," where some staff will speak English."]},{"k":"hs","s":["Health insurance cards"]},{"k":"p","s":["To get medically necessary state healthcare in Luxembourg, you need a Global Health Insurance Card (GHIC) or a European Health Insurance Card (EHIC)."]},{"k":"p","s":["The NHS’s ",["getting healthcare abroad webpage","https://www.nhs.uk/using-the-nhs/healthcare-abroad/apply-for-a-free-uk-global-health-insurance-card-ghic/"]," has details about:"]},{"k":"li","s":["how to apply for a GHIC"]},{"k":"li","s":["how to get temporary cover if you lose your card or it does not arrive in time"]},{"k":"li","s":["who qualifies for a new EHIC instead of a GHIC"]},{"k":"li","s":["what treatment counts as medically necessary"]},{"k":"p","s":["A GHIC or EHIC is not an alternative to travel insurance. You may have costs your GHIC or EHIC does not cover, including:"]},{"k":"li","s":["changes to travel and accommodation bookings"]},{"k":"li","s":["additional standard costs for treatment"]},{"k":"li","s":["medical repatriation to the UK"]},{"k":"li","s":["treatment that is ruled non-urgent"]},{"k":"li","s":["private healthcare"]},{"k":"li","s":["private clinics"]},{"k":"p","s":["There is also ",["guidance on healthcare if you’re living in Luxembourg","https://www.gov.uk/guidance/healthcare-in-luxembourg"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Luxembourg"]},{"k":"p","s":["Ambulance: 112"]},{"k":"p","s":["Fire: 112"]},{"k":"p","s":["Police: 113"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"]," including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Luxembourg"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Luxembourg"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find?serviceType=translatorsInterpreters&readNotice=ok&country=Luxembourg"]," in Luxembourg"]},{"k":"li","s":["dealing with a ",["death in Luxembourg","https://www.gov.uk/government/publications/bereavement-information-pack-luxembourg"]]},{"k":"li","s":["being ",["arrested in Luxembourg","https://www.gov.uk/government/publications/luxembourg-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/luxembourg/british-embassy-luxembourg"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/luxembourg/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Luxembourg","https://www.gov.uk/government/publications/overseas-business-risk-luxembourg"]," on how to manage political, economic, and business security-related risks."]}],"chars":15626,"change":"Updated information on European Entry-Exit System (EES) (‘Entry requirements’ page)."},"https://theconversation.com/trump-administration-may-fund-white-south-africans-to-document-hateful-rhetoric-and-violent-acts-296360":{"r":"conversation","at":"2026-11-20T14:37Z","sha":"6ef65176831d794d698c77f2694735599d56dee130ed3e398a54a41b180f5957","read":"https://theconversation.com/trump-administration-may-fund-white-south-africans-to-document-hateful-rhetoric-and-violent-acts-296360","bytes":185109,"x":"fulltext v1","title":"Trump administration may fund white South Africans to document ‘hateful rhetoric and violent acts’","by":[{"n":"Susan Appe","r":"Professor of Public Administration and Policy, University at Albany, State University of New York"},{"n":"David Campbell","r":"Professor of Public Administration, Binghamton University, State University of New York"}],"pub":"2026-11-20T13:45:01Z","mod":"","blocks":[{"k":"p","s":["The U.S. State Department ",["will reportedly give US$1 million to AfriForum","https://www.sabcnews.com/sabcnews/trump-administrations-looks-to-award-near-1m-to-afriforum/"],", a nongovernmental organization that advocates on behalf of Afrikaners in South Africa."]},{"k":"p","s":["The grant, first ",["reported by ProPublica on Nov. 5, 2026","https://www.propublica.org/article/afriforum-grant-trump-white-south-africans"],", would support research to document the “ ",["hateful rhetoric and violent acts","https://www.state.gov/releases/bureau-of-democracy-human-rights-and-labor/2026/08/documentation-of-hateful-rhetoric-targeting-minority-populations-in-south-africa"],"” experienced by ",["Afrikaners","https://www.nprillinois.org/2025-11-20/who-are-afrikaners-the-group-at-the-center-of-trumps-dispute-with-south-africa"]," – ",["descendants of white Dutch settlers","https://www.pbs.org/newshour/politics/fact-checking-trumps-claims-of-white-farmer-genocide-in-south-africa"]," who moved to South Africa in the 17th century."]},{"k":"p","s":["As scholars who study ",["foreign aid","https://scholar.google.com/citations?user=a8EwKzoAAAAJ&hl=en"]," and ",["civil society organizations","https://scholar.google.com/citations?user=VYsdAEIAAAAJ&hl=en"],", we would see U.S. support for AfriForum as a radical departure from the kinds of NGOs ",["the U.S. has funded in the past","https://www.ned.org/wp-content/uploads/2026/02/2025-Annual-Report.pdf"],"."]},{"k":"h","s":["Supporting democracy by funding NGOs"]},{"k":"p","s":["The U.S. used foreign aid for decades to support efforts to build democracy abroad, enhance governance and ",["strengthen human rights protections","https://2021-2025.state.gov/u-s-achievements-in-advancing-human-rights-globally/"],"."]},{"k":"p","s":["Until the second Trump administration, the primary government agencies distributing this assistance were the U.S. Agency for International Development, the State Department and the National Endowment for Democracy."]},{"k":"p","s":["Past administrations called this assistance “ ",["fundamental","https://www.congress.gov/crs-product/IN12523"],"” to the goals of U.S. foreign policy. By the end of President Joe Biden’s term, funding for democracy promotion had reached almost ",["$3 billion annually","https://dx.doi.org/10.1353/sais.2026.a1000457"],"."]},{"k":"p","s":["Some of this money has ",["supported NGOs engaged","https://obamawhitehouse.archives.gov/the-press-office/2015/09/29/fact-sheet-us-support-civil-society"]," in civic participation and media independence. These efforts had been particularly important in fragile states and fledgling democracies, where ",["civil society is especially at risk","https://www.ssoar.info/ssoar/bitstream/handle/document/113371/ssoar-2026-gessner_et_al-Backsliding_Democracy_The_Crisis_for.pdf"],"."]},{"k":"p","s":["NGOs can also play an important role in reducing risks of violence between different ethnic and religious groups. By raising awareness about past atrocities, they can help ",["stave off future violence","https://doi.org/10.1002/pad.1995"],"."]},{"k":"h","s":["Slashing foreign aid"]},{"k":"p","s":["The Trump administration suspended most ",["U.S. foreign aid in January 2025","https://www.whitehouse.gov/presidential-actions/2025/01/reevaluating-and-realigning-united-states-foreign-aid/"],", soon after Donald Trump was sworn in as president for a second time."]},{"k":"p","s":["It then ",["dismantled USAID","https://www.npr.org/2025/07/01/nx-s1-5451372/usaid-officially-shuts-down-and-merges-remaining-operations-with-state-department"],", the federal agency previously responsible for foreign aid and development assistance, and the White House compelled Congress to ",["rescind billions of dollars of foreign aid spending","https://www.npr.org/2025/07/18/nx-s1-5469912/npr-congress-rescission-funding-trumpe"],". It has continued to take steps in that direction with or ",["without lawmakers’ cooperation","https://www.cnn.com/2026/11/14/world/trump-administration-foreign-aid-global-health-diverted-intl"],"."]},{"k":"p","s":["As a result, many ",["lifesaving public health programs","https://www.simonandschuster.com/books/Into-the-Wood-Chipper/Nicholas-Enrich/9781668226957"]," lost funding. This policy change has had an ",["enormous human toll","https://doi.org/10.1016/s0140-6736(25)01186-9"],", which public health ",["researchers have begun to quantify","https://www.impactcounter.com/dashboard?view=table&sort=title&order=asc"],"."]},{"k":"p","s":["In addition, democracy assistance has been severely cut. ",["USAID’s Democracy Fund","https://carnegieendowment.org/research/2025/03/does-us-democracy-aid-have-a-future"],", which funded programs dedicated to building democratic institutions and promoting fair elections and respect for human rights, was eliminated. The Department of State’s and National Endowment for Democracy’s ",["funding and staffing","https://www.politico.com/news/2025/05/29/rubio-human-rights-state-00374606"]," for ",["promoting democracy were also slashed","https://www.congress.gov/crs_external_products/R/PDF/R49019/R49019.3.pdf"],"."]},{"k":"h","s":["Claiming there’s a ‘white genocide’"]},{"k":"p","s":["In our research on NGOs that work on promoting democracy and the prevention of violence, we have seen and documented the ",["benefits of these efforts","https://ssir.org/articles/entry/preventing-identity-based-violence-in-conflict-zones"],". The organizations we have studied emphasize how people in South Africa and other countries with a history of identity-based violence can learn to live together across racial, ethnic and religious divides."]},{"k":"p","s":["By contrast, ",["AfriForum seeks to lift up Afrikaner identity and history","https://www.propublica.org/article/afriforum-grant-trump-white-south-africans"],", ",["without any evident effort","https://www.cfr.org/articles/us-and-foreign-governments-should-be-skeptical-afriforums-lobbying"]," to bridge the divide between Afrikaners and other racial groups in South Africa."]},{"k":"p","s":["It champions causes that have contributed to what South African President Cyril Ramaphosa, scholars and other analysts call a false narrative of a “ ",["white genocide","https://doi.org/10.3389/fpos.2026.1886481"],"” in that country."]},{"k":"p","s":["In fact, researchers have found that Afrikaners and other white people in South Africa are less likely to be ",["victims of crime","https://www.bbc.com/news/articles/cgr5xe7z0y0o"]," and ",["other forms of violence","https://www.bbc.com/news/articles/cgr5xe7z0y0o"]," compared to other ethnic and racial groups in South Africa."]},{"k":"p","s":["By funding AfriForum, the State Department would be elevating the ",["dubious claims the group makes","https://theconversation.com/trump-and-south-africa-what-is-white-victimhood-and-how-is-it-linked-to-white-supremacy-249648"]," about the oppression of Afrikaners in South Africa."]},{"k":"p","s":["And ",["the Trump administration’s embrace","https://theconversation.com/the-american-fixation-on-white-afrikaners-in-south-africa-stretches-back-nearly-a-century-270145"]," of this false narrative goes beyond this grant for AfriForum. It explains why the U.S. has ",["allowed thousands of white South Africans","https://za.usembassy.gov/refugee-admissions-program-for-south-africans/"]," to come to the U.S. as refugees while denying admission to ",["nearly all other refugees","https://www.congress.gov/crs-product/IF13277"]," from the rest of the world."]}],"chars":3987},"https://theconversation.com/mark-carneys-fight-against-donald-trump-wont-make-canada-stronger-296186":{"r":"conversation","at":"2026-11-22T13:52Z","sha":"23c81f760aa14faebe2ce92c8d3ba0c13fa523fbe950b21a77f3ccb4aa426c6f","read":"https://theconversation.com/mark-carneys-fight-against-donald-trump-wont-make-canada-stronger-296186","bytes":186381,"x":"fulltext v1","title":"Mark Carney’s fight against Donald Trump won’t make Canada stronger","by":[{"n":"Peter Dietsch","r":"Professor, Department of Philosophy, University of Victoria"}],"pub":"2026-11-22T12:28:11Z","mod":"","blocks":[{"k":"p","s":["Prime Minister Mark Carney is riding a wave of domestic support and has emerged as the ",["global poster child","https://www.newsweek.com/hillary-clinton-canadas-mark-carney-leader-of-free-world-12719493"]," of a cautious but firm resistance to American bullies. He stood up to Donald Trump long before the ",["recent Democratic landslide","https://edition.cnn.com/2026/11/05/politics/live-news/midterm-election-congress"]," in the midterm elections in the United States."]},{"k":"p","s":["A central plank of Carney’s strategy consists of reducing Canada’s economic dependence on the U.S. by luring massive international investment to the country. Much of this investment into his ",["“Projects of National Interest”","https://www.canada.ca/en/privy-council/major-projects-office/projects/national.html"]," will flow to infrastructure allowing Canada’s vast natural resources to access markets outside of North America."]},{"k":"p","s":["It would seem the midterm election results vindicate Carney. Yet, on closer inspection, things are more complicated. While Carney’s goal is commendable — a stable, sovereign Canada — the means he’s employing will arguably move Canada closer to the model of a society that is championed by … Donald Trump."]},{"k":"h","s":["Corporations benefit"]},{"k":"p","s":["Consider the planned ",["“mega tax deduction”","https://www.canada.ca/en/department-finance/news/2026/09/government-of-canada-introduces-new-productivity-mega-deduction-to-boost-canadas-advantage-as-the-most-competitive-g7-country-for-new-business-inve.html"]," designed to spur investment in pipelines, ports and extraction projects."]},{"k":"p","s":["The main beneficiaries would be multinational corporations and their shareholders, not Canadians. True, the investments would create jobs, but it’s worth noting that workers on both sides of the Canada-U.S. border have not received much of a share of growth in the last four decades."]},{"k":"p","s":["Other cases, such as the plan to privatize four large Canadian airports, ",["are a classic short-term government cash grab","https://spp.ucalgary.ca/publications/a-review-and-assessment-of-privatization-in-canada"],"."]},{"k":"p","s":["Compared to ",["the Stellantis","https://www.ctvnews.ca/video/2026/11/15/should-the-government-have-acted-sooner-against-stellantis/"]," and ",["Stelco debacles","https://www.cbc.ca/news/politics/stelco-recalling-175-laid-off-workers-9.7420949"]," — when two major manufacturers failed to uphold job and production commitments made to Ottawa in exchange for federal backing or foreign-takeover approval — the federal government has a stronger position in the resource sector. That’s because the resources are located on Canadian soil."]},{"k":"p","s":["This opens up policy alternatives, which could include:"]},{"k":"li","s":["Moving towards the Danish model of ",["industrial foundations","https://www.tifp.dk/en/"],", where some profits are earmarked for social and environmental causes."]},{"k":"li","s":["Higher royalties from natural resource licences, which could be efficient in generating more for public coffers even if they marginally lowered private investment."]},{"k":"li","s":["Boosting the role of the ",["Canada Infrastructure Bank","https://cib-bic.ca/"]," to provide investment without loss of sovereignty, tied to Canada’s airports and ports."]},{"k":"h","s":["Eroding democratic norms"]},{"k":"p","s":["In addition to the political substance, the Carney government’s efforts weaken democratic accountability."]},{"k":"p","s":["The omnibus ",["Bill C-39","https://www.parl.ca/DocumentViewer/en/45-1/bill/C-39/first-reading"]," before Parliament weakens the rights of workers, non-governmental organizations and First Nations to contest the decisions made in the name of economic growth and “economic sovereignty.”"]},{"k":"p","s":["Read more: ",["What Bill C-39’s loosened environmental regulations could mean for Canadians","https://theconversation.com/what-bill-c-39s-loosened-environmental-regulations-could-mean-for-canadians-294851"]]},{"k":"p","s":["Some First Nations probably feel the same way about Ottawa’s economic bulldozer strategy as Canadians feel about Trump’s actions. The ",["Neskantaga First Nation’s battle","https://forensic-architecture.org/investigation/neskantaga"]," to protect their homelands in northern Ontario is just one example."]},{"k":"h","s":["Sustainability"]},{"k":"p","s":["Carney’s strategy is doubling down on the fossil fuel sector in Canada, too. This favours ",["profit extraction","https://doi.org/10.1080/13563467.2021.1926957"]," and concentrated economic interests both at home and abroad over ",["lower-income Canadians who are most likely to suffer","https://www.theguardian.com/environment/commentisfree/2023/nov/23/climate-emergency-crisis-conference-cop-28"]," from the consequences of climate change in terms of extreme weather, drought, wildfire and smoke."]},{"k":"p","s":["Once again, alternatives exist. Rather than export raw materials cheaply, why not invest in the processing of lumber, oil, gas, metals and minerals at home? For decades, part of Canada’s resource curse has been that most of the processing and economic value creation ( ",["and job creation","https://doi.org/10.23941/ejpe.v11i2.340"],") happens abroad, and Canadians pay dearly to purchase back the final products."]},{"k":"p","s":["Promoting forms of worker or producer co-operatives and vocational training programs would allow more evenly distributed forms of economic growth without increasing Canada’s carbon footprint. What’s more, investing in renewables has vast potential and is less prone to monopolizing profits."]},{"k":"h","s":["Carney’s amnesia?"]},{"k":"p","s":["In sum, Carney’s Projects of National Interest look more like Projects of National Inequality and Environmental Destruction than measures that will promote Canada’s interests in a socially and environmentally sustainable fashion."]},{"k":"p","s":["Even without some of the more repulsive and narcissistic characteristics of Trump’s presidency, the economic policy outcome will be a country that is closer than ever before to Trump’s ideal for the U.S."]},{"k":"p","s":["The fact that someone as qualified and experienced as Carney falls into this trap is both surprising and to be expected at the same time."]},{"k":"p","s":["It’s surprising because Carney is well aware that policy measures have unintended, but foreseeable, negative consequences. In 2014, as governor of the Bank of England, he conceded that ",["“the distributional consequences of the response to the financial crisis have been significant,”","https://www.bis.org/speeches/20140528-inclusive-capitalism-creating-sense-systemic"]," exacerbating inequality."]},{"k":"p","s":["He also founded the ",["Network for Greening the Financial System","https://www.ngfs.net/en"]," in 2017, a group of central banks analyzing and guarding against the financial risks of climate change. In short, he sounded like a champion of sustainability."]},{"k":"p","s":["A striking case of amnesia about this former life seems to have befallen Carney since becoming prime minister. Yet it also has simple explanations."]},{"k":"p","s":["While corporate lobbyists in Ottawa may not be as powerful as they are in the U.S. capital, they clearly have substantial influence. In addition, Carney’s background as a banker predisposes him to favour financial interests over those of working Canadians when push comes to shove."]},{"k":"p","s":["What’s the point of fighting Trump when the price you pay is to import some elements of Trumpism to Canada? The consequences of Carney’s policy agenda, in terms of exacerbating the twin crises of economic inequality and environmental degradation, could be felt in Canada long after Trump has left the Oval Office."]}],"chars":5776},"https://theconversation.com/that-black-friday-countdown-says-the-sale-ends-in-ten-minutes-but-is-it-real-296501":{"r":"conversation","at":"2026-11-25T00:43Z","sha":"f256b8fe52634e58305218873a129ebc9d3805c6d47498477dad4bfcdaa940ea","read":"https://theconversation.com/that-black-friday-countdown-says-the-sale-ends-in-ten-minutes-but-is-it-real-296501","bytes":178575,"x":"fulltext v1","title":"That Black Friday countdown says the sale ends in ten minutes. But is it real?","by":[{"n":"Meena Jha","r":"Associate Professor, College of Information & Communication Technology, School of Engineering and Technology, CQUniversity Australia"}],"pub":"2026-11-25T00:01:51Z","mod":"","blocks":[{"k":"p","s":["You’re shopping online when you spot a pair of headphones at half price. A countdown timer says the sale ends in ten minutes. Another message warns only three are left."]},{"k":"p","s":["You weren’t planning to buy them today. But what if you miss out?"]},{"k":"p","s":["Black Friday arrives on November 27 and Australian shoppers will encounter plenty of offers like these. Some will be genuine bargains. But some businesses may use misleading tactics to pressure people into buying before they’ve had time to think."]},{"k":"h","s":["Australians are spending more on Black Friday"]},{"k":"p","s":["One leading market research company ",["is predicting","https://www.roymorgan.com/findings/10368-arc-roy-morgan-black-friday-cyber-monday-spending-forecasts-2026"]," Australians will spend a record $7.2 billion during the four-day Black Friday to Cyber Monday sales period from November 27-30. That’s 5.5% more than last year. It predicts shoppers to spend an average of $920 – a $116 rise from 2025."]},{"k":"p","s":["Saving money is a major motivation for these kind of sales. Australian research from ",["2025 found","https://lens.monash.edu/tis-the-season-for-sales-black-friday-rings-in-the-christmas-season/"]," 64% of Australian shoppers consider price discounts important when making purchases, while 89% wait for sales or promotions before buying products in at least one category."]},{"k":"p","s":["For retailers, this presents a major opportunity. But some are pushing the boundaries to try to turn browsing into buying."]},{"k":"h","s":["Why do online stores make us feel rushed?"]},{"k":"p","s":["Some online platforms mislead or manipulate people into taking actions they otherwise might avoid. These tricks are known as “ ",["dark patterns","https://www.which.co.uk/policy-and-insight/article/dark-patterns-2026-aCroI9S4updG"],"”."]},{"k":"p","s":["A familiar example is the countdown timer."]},{"k":"p","s":["Seeing a clock ticking towards zero ",["creates a sense of urgency","https://www.accc.gov.au/media-release/accc-warns-against-misleading-%E2%80%98storewide%E2%80%99-or-%E2%80%98limited-time%E2%80%99-black-friday-sales-claims"],". Instead of comparing prices or considering whether you need the product, you may rush to complete the purchase."]},{"k":"p","s":["Of course, genuine time-limited offers are perfectly legitimate. The problem arises when the deadline isn’t real."]},{"k":"p","s":["But how can shoppers tell?"]},{"k":"p","s":["One warning sign is a countdown timer that resets when it reaches zero. Another is when the same discount remains available after the advertised deadline."]},{"k":"p","s":["There is no foolproof way to tell whether a countdown deadline is genuine beforehand. The safest approach is not to let the timer dictate your decision. Compare prices with other retailers, check whether the product meets your needs and avoid buying simply because the clock is running out."]},{"k":"h","s":["It’s not just countdown timers"]},{"k":"p","s":["Another tactic is creating an impression that products are running out. Messages such as “only two left in stock” or “20 people are viewing this item” can make shoppers worry someone else will buy the product first."]},{"k":"p","s":["Such information can be helpful when accurate. But these scarcity claims can pressure people into making unnecessary purchases."]},{"k":"p","s":["It’s difficult because shoppers cannot independently verify a retailer’s stock levels. One practical step is to check whether the product is available elsewhere rather than rushing to buy it."]},{"k":"p","s":["Discount labels can also be deceptive."]},{"k":"p","s":["Imagine a jacket advertised for $100, reduced from $200. It appears to be a 50% saving. But what if the jacket was never sold at $200, or was only briefly offered at that price?"]},{"k":"p","s":["A crossed-out price creates an impression of savings that may not reflect the product’s usual selling price."]},{"k":"p","s":["These tactics can be especially persuasive when shoppers are already searching for bargains."]},{"k":"h","s":["What are regulators doing?"]},{"k":"p","s":["In September 2026, the ",["Australian Competition and Consumer Commission (ACCC)","https://www.accc.gov.au/media-release/james-lane-and-vuly-pay-penalties-for-allegedly-making-misleading-representations-during-last-year%E2%80%99s-black-friday-sales"]," announced retailers Vuly and James Lane had paid $39,600 and $19,800 penalties respectively following allegations of misleading Black Friday promotions."]},{"k":"p","s":["Then on November 10, the ACCC announced ",["another investigation of Black Friday","https://www.accc.gov.au/media-release/accc-warns-against-misleading-%E2%80%98storewide%E2%80%99-or-%E2%80%98limited-time%E2%80%99-black-friday-sales-claims"]," sales advertising. It will examine potentially misleading countdown timers, discount claims, low-stock warnings and testimonials."]},{"k":"p","s":["For the first time, its Black Friday checks will extend across websites, emails and social media."]},{"k":"p","s":["The watchdog’s earlier investigation found concerning advertising claims in about half of the 50 retailers reviewed. ",["Under Australian consumer law","https://www.accc.gov.au/business/advertising-and-promotions/false-or-misleading-claims"],", businesses cannot make false or misleading claims about prices, discounts or promotions."]},{"k":"p","s":["Australia isn’t alone."]},{"k":"p","s":["The ",["European Union’s Digital Services Act","https://digital-strategy.ec.europa.eu/en/policies/digital-services-act"]," aims to restrict deceptive website designs on online platforms."]},{"k":"p","s":["In the United States, ",["the Federal Trade Commission Act","https://www.ftc.gov/about-ftc/mission/enforcement-authority"]," prohibits unfair or deceptive business practices."]},{"k":"p","s":["These efforts recognise how a website presents information can influence purchasing decisions."]},{"k":"p","s":["Read more: ",["Here’s what Black Friday sales shopping does to your brain","https://theconversation.com/heres-what-black-friday-sales-shopping-does-to-your-brain-269591"]]},{"k":"h","s":["How can you avoid the traps?"]},{"k":"p","s":["Black Friday can offer genuine savings. But a few simple checks can help you avoid buying something you’ll later regret:"]},{"k":"li","s":["compare prices: check the same product at other retailers. ",["Price history tools","https://www.ozbargain.com.au/wiki/list_of_price_comparison_sites"]," can help reveal whether a discount is genuine"]},{"k":"li","s":["question the countdown: don’t assume a sale will disappear when the timer reaches zero"]},{"k":"li","s":["read the conditions: check whether advertised discounts apply to the products you want"]},{"k":"li","s":["look at the final price: delivery fees and other charges can inflate your final payment"]},{"k":"li","s":["check the seller: be cautious of unfamiliar websites offering unusually large discounts. Fake online stores also use urgency to attract shoppers"]},{"k":"li","s":["decide before browsing: make a shopping list and set a budget so you’re less tempted by unexpected offers."]},{"k":"p","s":["If you encounter a potentially misleading promotion, you can ",["report it to the ACCC","https://www.accc.gov.au/about-us/contact-us-or-report-an-issue"],"."]},{"k":"h","s":["Happy bargain hunting – but be smart"]},{"k":"p","s":["Black Friday is meant to help shoppers save money, not pressure them into rushed decisions."]},{"k":"p","s":["A genuine bargain should still be a good deal when the countdown clock is gone."]}],"chars":5418}};
